-- BRASIS CULTURAL v2 • serve para projeto novo ou atualização da versão anterior.
-- Preserva contas e histórico antigo; a pontuação passa a contar apenas a jornada cultural.
begin;
create table if not exists public.profiles (
 id uuid primary key references auth.users(id) on delete cascade,
 nickname text not null check (char_length(nickname) between 2 and 40),
 points integer not null default 0 check(points >= 0),
 created_at timestamptz not null default now()
);
create table if not exists public.missions (
 id bigint generated always as identity primary key,
 title text not null, description text not null, category text not null,
 region text not null, difficulty text not null check(difficulty in ('Fácil','Médio','Difícil')),
 points integer not null check(points > 0), instructions text[] not null,
 icon text not null default 'eco', featured boolean not null default false,
 active boolean not null default true
);
create table if not exists public.user_missions (
 user_id uuid not null references public.profiles on delete cascade,
 mission_id bigint not null references public.missions,
 status text not null check(status in ('in_progress','completed')),
 started_at timestamptz not null default now(), completed_at timestamptz,
 primary key(user_id, mission_id),
 check((status='completed') = (completed_at is not null))
);
create table if not exists public.achievements (
 id text primary key, name text not null, description text not null,
 icon text not null, metric text not null check(metric in ('missions','days','points')),
 target integer not null check(target > 0)
);
create table if not exists public.user_achievements (
 user_id uuid not null references public.profiles on delete cascade,
 achievement_id text not null references public.achievements,
 unlocked_at timestamptz not null default now(), primary key(user_id,achievement_id)
);

alter table public.profiles add column if not exists legacy_points integer;
alter table public.missions add column if not exists mission_code text;
alter table public.missions add column if not exists region_order integer;
alter table public.missions add column if not exists step_order integer;
alter table public.missions add column if not exists lesson text;
alter table public.missions add column if not exists quiz_question text;
alter table public.missions add column if not exists answer_options text[];
alter table public.missions add column if not exists source_url text;
alter table public.user_missions add column if not exists note text;
alter table public.achievements add column if not exists active boolean not null default true;
alter table public.achievements drop constraint if exists achievements_metric_check;
alter table public.achievements add constraint achievements_metric_check check(metric in ('missions','days','points','regions'));
create unique index if not exists missions_code_unique on public.missions(mission_code);
create index if not exists profiles_ranking on public.profiles(points desc,created_at,id);
create table if not exists public.mission_answers(
 mission_id bigint primary key references public.missions(id) on delete cascade,
 correct_index integer not null check(correct_index between 0 and 2)
);
-- Respostas ficam fora da tabela legível pelo cliente.
alter table public.mission_answers enable row level security;
revoke all on public.mission_answers from public,anon,authenticated;
update public.profiles set legacy_points=points where legacy_points is null;
update public.missions set active=false where mission_code is null;
update public.achievements set active=false where id in ('first','five','days','points');
insert into public.missions(title,description,category,region,difficulty,points,instructions,icon,featured,mission_code,region_order,step_order,lesson,quiz_question,answer_options,source_url,active) values('No compasso do carimbó','O carimbó é uma expressão cultural paraense que reúne música, dança e encontros comunitários. Os tambores chamados curimbós ajudam a marcar seu ritmo. Povos indígenas, populações negras e outras comunidades participam dessa história, que continua sendo criada por seus mestres e grupos. O Norte tem muitas culturas: esta é uma primeira janela, não um retrato de toda a região.','Música & dança','Norte','Fácil',80,array['Imagine que você ouviu uma apresentação de carimbó. Que detalhe gostaria de observar: os instrumentos, a dança ou a história do grupo? Registre sua escolha e o motivo.'],'music',true,'no_carimbo',1,1,'O carimbó é uma expressão cultural paraense que reúne música, dança e encontros comunitários. Os tambores chamados curimbós ajudam a marcar seu ritmo. Povos indígenas, populações negras e outras comunidades participam dessa história, que continua sendo criada por seus mestres e grupos. O Norte tem muitas culturas: esta é uma primeira janela, não um retrato de toda a região.','Qual instrumento ajuda a marcar o ritmo do carimbó?',array['Curimbó, um tipo de tambor','Sombrinha de frevo','Viola de cocho'],'https://bcr.iphan.gov.br/bens-culturais/carimbo/',true) on conflict(mission_code) do update set title=excluded.title,description=excluded.description,category=excluded.category,region=excluded.region,difficulty=excluded.difficulty,points=excluded.points,instructions=excluded.instructions,icon=excluded.icon,featured=excluded.featured,region_order=excluded.region_order,step_order=excluded.step_order,lesson=excluded.lesson,quiz_question=excluded.quiz_question,answer_options=excluded.answer_options,source_url=excluded.source_url,active=excluded.active;
insert into public.mission_answers select id,0 from public.missions where mission_code='no_carimbo' on conflict(mission_id) do update set correct_index=excluded.correct_index;
insert into public.missions(title,description,category,region,difficulty,points,instructions,icon,featured,mission_code,region_order,step_order,lesson,quiz_question,answer_options,source_url,active) values('Uma cuia, muitas histórias','No Baixo Amazonas, fazer cuias envolve saberes transmitidos entre gerações de artesãs. A casca do fruto da cuieira é trabalhada para se transformar em um recipiente, que pode receber ornamentação. Mais que um objeto, a cuia carrega trabalho, autoria e memória. Os modos de fazer e decorar variam entre comunidades e pessoas.','Artes & saberes','Norte','Médio',90,array['Crie uma ideia de estampa autoral para uma cuia e descreva duas formas ou cores que usaria. Não copie grafismos sagrados ou de povos específicos.'],'art',false,'no_cuias',1,2,'No Baixo Amazonas, fazer cuias envolve saberes transmitidos entre gerações de artesãs. A casca do fruto da cuieira é trabalhada para se transformar em um recipiente, que pode receber ornamentação. Mais que um objeto, a cuia carrega trabalho, autoria e memória. Os modos de fazer e decorar variam entre comunidades e pessoas.','De onde vem a matéria-prima das cuias tradicionais?',array['De blocos de vidro','Do fruto da cuieira','De chapas de metal'],'https://bcr.iphan.gov.br/bens-culturais/modos-de-fazer-cuias-do-baixo-amazonas/',true) on conflict(mission_code) do update set title=excluded.title,description=excluded.description,category=excluded.category,region=excluded.region,difficulty=excluded.difficulty,points=excluded.points,instructions=excluded.instructions,icon=excluded.icon,featured=excluded.featured,region_order=excluded.region_order,step_order=excluded.step_order,lesson=excluded.lesson,quiz_question=excluded.quiz_question,answer_options=excluded.answer_options,source_url=excluded.source_url,active=excluded.active;
insert into public.mission_answers select id,1 from public.missions where mission_code='no_cuias' on conflict(mission_id) do update set correct_index=excluded.correct_index;
insert into public.missions(title,description,category,region,difficulty,points,instructions,icon,featured,mission_code,region_order,step_order,lesson,quiz_question,answer_options,source_url,active) values('Sabores que contam histórias','O tacacá é uma preparação amazônica frequentemente servida em cuia. Tucupi, goma de mandioca e jambu estão entre seus ingredientes; o camarão também aparece em muitas versões. As pessoas que o preparam e vendem mantêm conhecimentos e relações de convivência. Receitas e costumes variam: uma comida pode contar muitas histórias sem ter uma versão única.','Sabores','Norte','Médio',100,array['Escolha um ingrediente citado e escreva algo que gostaria de descobrir sobre ele. Não é preciso comprar, cozinhar nem provar alimentos para jogar.'],'food',false,'no_tacaca',1,3,'O tacacá é uma preparação amazônica frequentemente servida em cuia. Tucupi, goma de mandioca e jambu estão entre seus ingredientes; o camarão também aparece em muitas versões. As pessoas que o preparam e vendem mantêm conhecimentos e relações de convivência. Receitas e costumes variam: uma comida pode contar muitas histórias sem ter uma versão única.','Qual conjunto reúne ingredientes associados ao tacacá?',array['Café, trigo e chocolate','Arroz, feijão e farofa','Tucupi, goma de mandioca e jambu'],'https://pesquisaescolar.fundaj.gov.br/pt-br/artigo/tacaca/',true) on conflict(mission_code) do update set title=excluded.title,description=excluded.description,category=excluded.category,region=excluded.region,difficulty=excluded.difficulty,points=excluded.points,instructions=excluded.instructions,icon=excluded.icon,featured=excluded.featured,region_order=excluded.region_order,step_order=excluded.step_order,lesson=excluded.lesson,quiz_question=excluded.quiz_question,answer_options=excluded.answer_options,source_url=excluded.source_url,active=excluded.active;
insert into public.mission_answers select id,2 from public.missions where mission_code='no_tacaca' on conflict(mission_id) do update set correct_index=excluded.correct_index;
insert into public.missions(title,description,category,region,difficulty,points,instructions,icon,featured,mission_code,region_order,step_order,lesson,quiz_question,answer_options,source_url,active) values('Um passo cheio de cor','O frevo reúne música e dança e tem fortes vínculos com o carnaval de Recife e Olinda. Suas relações com bandas e com a capoeira fazem parte dessa trajetória. A pequena sombrinha colorida virou uma marca visual dos passistas. Há diferentes modalidades de frevo e muitas maneiras de participar dessa manifestação coletiva.','Música & dança','Nordeste','Fácil',100,array['Imagine uma sombrinha de frevo para seu avatar. Escolha três cores e explique como elas combinam com a energia da apresentação.'],'music',true,'ne_frevo',2,1,'O frevo reúne música e dança e tem fortes vínculos com o carnaval de Recife e Olinda. Suas relações com bandas e com a capoeira fazem parte dessa trajetória. A pequena sombrinha colorida virou uma marca visual dos passistas. Há diferentes modalidades de frevo e muitas maneiras de participar dessa manifestação coletiva.','A quais cidades o frevo está especialmente ligado?',array['Recife e Olinda','Manaus e Belém','Curitiba e Florianópolis'],'https://bcr.iphan.gov.br/bens-culturais/frevo/',true) on conflict(mission_code) do update set title=excluded.title,description=excluded.description,category=excluded.category,region=excluded.region,difficulty=excluded.difficulty,points=excluded.points,instructions=excluded.instructions,icon=excluded.icon,featured=excluded.featured,region_order=excluded.region_order,step_order=excluded.step_order,lesson=excluded.lesson,quiz_question=excluded.quiz_question,answer_options=excluded.answer_options,source_url=excluded.source_url,active=excluded.active;
insert into public.mission_answers select id,0 from public.missions where mission_code='ne_frevo' on conflict(mission_id) do update set correct_index=excluded.correct_index;
insert into public.missions(title,description,category,region,difficulty,points,instructions,icon,featured,mission_code,region_order,step_order,lesson,quiz_question,answer_options,source_url,active) values('Sua história em versos','A literatura de cordel combina poesia, oralidade e folhetos impressos. Seus versos contam histórias, comentam acontecimentos e circulam por feiras, encontros e outros espaços. A xilogravura é uma arte frequentemente associada às capas, embora não seja a única técnica usada. O cordel tem fortes raízes nordestinas e é produzido em diferentes partes do país.','Literatura','Nordeste','Médio',110,array['Escreva dois versos autorais sobre sua viagem pelos Brasis. Você pode brincar com uma rima; não precisa seguir uma métrica tradicional.'],'story',false,'ne_cordel',2,2,'A literatura de cordel combina poesia, oralidade e folhetos impressos. Seus versos contam histórias, comentam acontecimentos e circulam por feiras, encontros e outros espaços. A xilogravura é uma arte frequentemente associada às capas, embora não seja a única técnica usada. O cordel tem fortes raízes nordestinas e é produzido em diferentes partes do país.','O que caracteriza a literatura de cordel?',array['Somente esculturas de pedra','Histórias em versos e tradição oral','Somente mapas rodoviários'],'https://bcr.iphan.gov.br/bens-culturais/literatura-de-cordel/',true) on conflict(mission_code) do update set title=excluded.title,description=excluded.description,category=excluded.category,region=excluded.region,difficulty=excluded.difficulty,points=excluded.points,instructions=excluded.instructions,icon=excluded.icon,featured=excluded.featured,region_order=excluded.region_order,step_order=excluded.step_order,lesson=excluded.lesson,quiz_question=excluded.quiz_question,answer_options=excluded.answer_options,source_url=excluded.source_url,active=excluded.active;
insert into public.mission_answers select id,1 from public.missions where mission_code='ne_cordel' on conflict(mission_id) do update set correct_index=excluded.correct_index;
insert into public.missions(title,description,category,region,difficulty,points,instructions,icon,featured,mission_code,region_order,step_order,lesson,quiz_question,answer_options,source_url,active) values('O saber por trás do tabuleiro','O ofício das baianas de acarajé envolve conhecimentos culinários, indumentária, relações comunitárias e referências das religiões de matriz africana. O tabuleiro é parte desse universo. Conhecer o ofício significa reconhecer o trabalho e a história de suas detentoras. A prática não se limita a um alimento nem ocorre apenas na Bahia.','Sabores','Nordeste','Médio',120,array['Escreva uma pergunta respeitosa que você faria a uma baiana sobre sua história e seu ofício. Não é necessário entrevistar alguém para concluir.'],'food',false,'ne_acaraje',2,3,'O ofício das baianas de acarajé envolve conhecimentos culinários, indumentária, relações comunitárias e referências das religiões de matriz africana. O tabuleiro é parte desse universo. Conhecer o ofício significa reconhecer o trabalho e a história de suas detentoras. A prática não se limita a um alimento nem ocorre apenas na Bahia.','Por que o ofício das baianas vai além de uma receita?',array['Porque não tem relação com comida','Porque é igual em todos os lugares','Porque reúne saberes, histórias e relações culturais'],'https://bcr.iphan.gov.br/bens-culturais/oficio-das-baianas-de-acaraje/',true) on conflict(mission_code) do update set title=excluded.title,description=excluded.description,category=excluded.category,region=excluded.region,difficulty=excluded.difficulty,points=excluded.points,instructions=excluded.instructions,icon=excluded.icon,featured=excluded.featured,region_order=excluded.region_order,step_order=excluded.step_order,lesson=excluded.lesson,quiz_question=excluded.quiz_question,answer_options=excluded.answer_options,source_url=excluded.source_url,active=excluded.active;
insert into public.mission_answers select id,2 from public.missions where mission_code='ne_acaraje' on conflict(mission_id) do update set correct_index=excluded.correct_index;
insert into public.missions(title,description,category,region,difficulty,points,instructions,icon,featured,mission_code,region_order,step_order,lesson,quiz_question,answer_options,source_url,active) values('O som da viola de cocho','A viola de cocho é um instrumento associado a práticas culturais de Mato Grosso e Mato Grosso do Sul. Seu modo de fazer envolve trabalho artesanal em madeira e conhecimentos transmitidos entre gerações. Ela participa de expressões como o cururu e o siriri. Conhecer o som também é conhecer as pessoas que fabricam, tocam e ensinam.','Música & saberes','Centro-Oeste','Fácil',120,array['Se pudesse conversar com um artesão da viola, o que perguntaria sobre a construção ou o som do instrumento? Registre sua pergunta.'],'music',true,'co_viola',3,1,'A viola de cocho é um instrumento associado a práticas culturais de Mato Grosso e Mato Grosso do Sul. Seu modo de fazer envolve trabalho artesanal em madeira e conhecimentos transmitidos entre gerações. Ela participa de expressões como o cururu e o siriri. Conhecer o som também é conhecer as pessoas que fabricam, tocam e ensinam.','A viola de cocho está ligada especialmente a quais estados?',array['Mato Grosso e Mato Grosso do Sul','Pernambuco e Paraíba','Acre e Amapá'],'https://www.gov.br/iphan/pt-br/superintendencias/mato-grosso/patrimonio-imaterial',true) on conflict(mission_code) do update set title=excluded.title,description=excluded.description,category=excluded.category,region=excluded.region,difficulty=excluded.difficulty,points=excluded.points,instructions=excluded.instructions,icon=excluded.icon,featured=excluded.featured,region_order=excluded.region_order,step_order=excluded.step_order,lesson=excluded.lesson,quiz_question=excluded.quiz_question,answer_options=excluded.answer_options,source_url=excluded.source_url,active=excluded.active;
