insert into public.missions(title,description,category,region,difficulty,points,instructions,icon,featured,mission_code,region_order,step_order,lesson,quiz_question,answer_options,source_url,active) values('Uma cidade em festa','As cavalhadas fazem parte de festas em diferentes cidades de Goiás, incluindo Pirenópolis. Cavaleiros, roupas, música, preparação e participação comunitária compõem essas celebrações. Os sentidos atribuídos à festa e suas formas de organização variam entre os lugares. Para conhecer uma tradição, vale ouvir quem a realiza e distinguir a encenação festiva dos acontecimentos históricos.','Festas & encontros','Centro-Oeste','Médio',130,array['Imagine uma visita a uma festa local. Escreva dois detalhes culturais que você gostaria de observar e uma pergunta que faria aos participantes.'],'party',false,'co_festas',3,2,'As cavalhadas fazem parte de festas em diferentes cidades de Goiás, incluindo Pirenópolis. Cavaleiros, roupas, música, preparação e participação comunitária compõem essas celebrações. Os sentidos atribuídos à festa e suas formas de organização variam entre os lugares. Para conhecer uma tradição, vale ouvir quem a realiza e distinguir a encenação festiva dos acontecimentos históricos.','Além da encenação, o que ajuda a compreender uma festa?',array['Apenas contar os visitantes','Conhecer a preparação e ouvir a comunidade','Ignorar as histórias dos participantes'],'https://www.gov.br/iphan/pt-br/assuntos/noticias/com-a-retomada-das-cavalhadas-avanca-o-processo-de-registro-da-manifestacao-como-patrimonio-cultural-do-brasil',true) on conflict(mission_code) do update set title=excluded.title,description=excluded.description,category=excluded.category,region=excluded.region,difficulty=excluded.difficulty,points=excluded.points,instructions=excluded.instructions,icon=excluded.icon,featured=excluded.featured,region_order=excluded.region_order,step_order=excluded.step_order,lesson=excluded.lesson,quiz_question=excluded.quiz_question,answer_options=excluded.answer_options,source_url=excluded.source_url,active=excluded.active;
