insert into public.missions(title,description,category,region,difficulty,points,instructions,icon,featured,mission_code,region_order,step_order,lesson,quiz_question,answer_options,source_url,active) values('Uma capital desenhada','Brasília é conhecida pelo plano urbanístico de Lucio Costa e por edifícios projetados por Oscar Niemeyer. A cidade também foi construída pelo trabalho de pessoas vindas de muitas partes do Brasil, entre elas os chamados candangos. Conhecer uma cidade inclui olhar a arquitetura e perguntar sobre seus habitantes, seus trabalhos e suas memórias.','Arquitetura','Centro-Oeste','Médio',140,array['Descreva um lugar de encontro que você criaria para uma cidade: uma praça, biblioteca ou centro cultural. Que histórias poderiam acontecer ali?'],'building',false,'co_brasilia',3,3,'Brasília é conhecida pelo plano urbanístico de Lucio Costa e por edifícios projetados por Oscar Niemeyer. A cidade também foi construída pelo trabalho de pessoas vindas de muitas partes do Brasil, entre elas os chamados candangos. Conhecer uma cidade inclui olhar a arquitetura e perguntar sobre seus habitantes, seus trabalhos e suas memórias.','Quem foi o autor do plano urbanístico de Brasília?',array['Heitor Villa-Lobos','Machado de Assis','Lucio Costa'],'https://www.gov.br/iphan/pt-br/superintendencias/distrito-federal/patrimonio-mundial',true) on conflict(mission_code) do update set title=excluded.title,description=excluded.description,category=excluded.category,region=excluded.region,difficulty=excluded.difficulty,points=excluded.points,instructions=excluded.instructions,icon=excluded.icon,featured=excluded.featured,region_order=excluded.region_order,step_order=excluded.step_order,lesson=excluded.lesson,quiz_question=excluded.quiz_question,answer_options=excluded.answer_options,source_url=excluded.source_url,active=excluded.active;
