insert into public.missions(title,description,category,region,difficulty,points,instructions,icon,featured,mission_code,region_order,step_order,lesson,quiz_question,answer_options,source_url,active) values('A memória que dança','O jongo é uma expressão afro-brasileira em que tambores, canto e dança se encontram. Comunidades dos quatro estados do Sudeste mantêm e recriam essa prática. Os pontos cantados e as rodas podem transmitir memórias, vínculos e formas de expressão. Reconhecer essa história também é reconhecer o protagonismo das comunidades negras que a sustentam.','Música & memória','Sudeste','Fácil',140,array['Escreva uma frase explicando por que ouvir os mestres e as comunidades é importante para conhecer uma manifestação cultural.'],'music',true,'se_jongo',4,1,'O jongo é uma expressão afro-brasileira em que tambores, canto e dança se encontram. Comunidades dos quatro estados do Sudeste mantêm e recriam essa prática. Os pontos cantados e as rodas podem transmitir memórias, vínculos e formas de expressão. Reconhecer essa história também é reconhecer o protagonismo das comunidades negras que a sustentam.','Em quais estados do Sudeste há comunidades jongueiras?',array['Nos quatro estados da região','Somente em São Paulo','Somente no Rio de Janeiro'],'https://bcr.iphan.gov.br/bens-culturais/jongo-no-sudeste/',true) on conflict(mission_code) do update set title=excluded.title,description=excluded.description,category=excluded.category,region=excluded.region,difficulty=excluded.difficulty,points=excluded.points,instructions=excluded.instructions,icon=excluded.icon,featured=excluded.featured,region_order=excluded.region_order,step_order=excluded.step_order,lesson=excluded.lesson,quiz_question=excluded.quiz_question,answer_options=excluded.answer_options,source_url=excluded.source_url,active=excluded.active;
insert into public.mission_answers select id,0 from public.missions where mission_code='se_jongo' on conflict(mission_id) do update set correct_index=excluded.correct_index;
insert into public.missions(title,description,category,region,difficulty,points,instructions,icon,featured,mission_code,region_order,step_order,lesson,quiz_question,answer_options,source_url,active) values('Saberes à mesa','Os modos artesanais de fazer queijo em Minas Gerais envolvem técnicas, conhecimentos e relações sociais transmitidos entre gerações. As regiões produtoras apresentam particularidades: não existe um único queijo que represente todos os lugares. O saber de quem produz e a história da comunidade são parte do patrimônio, junto dos ingredientes e dos processos.','Sabores','Sudeste','Médio',150,array['Pense em um alimento que faz parte da história de sua família ou comunidade. Escreva seu nome e uma lembrança ou pergunta relacionada a ele.'],'food',false,'se_queijos',4,2,'Os modos artesanais de fazer queijo em Minas Gerais envolvem técnicas, conhecimentos e relações sociais transmitidos entre gerações. As regiões produtoras apresentam particularidades: não existe um único queijo que represente todos os lugares. O saber de quem produz e a história da comunidade são parte do patrimônio, junto dos ingredientes e dos processos.','O que também faz parte dos saberes de um queijo artesanal?',array['Apenas a embalagem','As técnicas e memórias dos produtores','Somente a aparência do produto'],'https://www.gov.br/iphan/pt-br/superintendencias/minas-gerais/patrimonio-imaterial',true) on conflict(mission_code) do update set title=excluded.title,description=excluded.description,category=excluded.category,region=excluded.region,difficulty=excluded.difficulty,points=excluded.points,instructions=excluded.instructions,icon=excluded.icon,featured=excluded.featured,region_order=excluded.region_order,step_order=excluded.step_order,lesson=excluded.lesson,quiz_question=excluded.quiz_question,answer_options=excluded.answer_options,source_url=excluded.source_url,active=excluded.active;
insert into public.mission_answers select id,1 from public.missions where mission_code='se_queijos' on conflict(mission_id) do update set correct_index=excluded.correct_index;
insert into public.missions(title,description,category,region,difficulty,points,instructions,icon,featured,mission_code,region_order,step_order,lesson,quiz_question,answer_options,source_url,active) values('Uma roda, muitas vozes','O samba reúne diferentes formas de cantar, tocar, dançar e conviver. No Rio de Janeiro, práticas como o partido-alto, o samba de terreiro e o samba-enredo fazem parte de sua história. As comunidades negras têm papel central nessa criação. Outras regiões também têm seus sambas: uma mesma palavra pode abrigar muitas expressões culturais.','Música & encontros','Sudeste','Médio',160,array['Escreva o nome de um instrumento que você gostaria de ouvir em uma roda e explique o motivo. Não é preciso reproduzir letras de músicas.'],'music',false,'se_samba',4,3,'O samba reúne diferentes formas de cantar, tocar, dançar e conviver. No Rio de Janeiro, práticas como o partido-alto, o samba de terreiro e o samba-enredo fazem parte de sua história. As comunidades negras têm papel central nessa criação. Outras regiões também têm seus sambas: uma mesma palavra pode abrigar muitas expressões culturais.','O samba pode ser entendido como...',array['Uma expressão sem participação comunitária','Uma prática de um único formato','Um conjunto de expressões musicais e de convivência'],'https://bcr.iphan.gov.br/bens-culturais/matrizes-do-samba-no-rio-de-janeiro-partido-alto-samba-de-terreiro-e-samba-enredo/',true) on conflict(mission_code) do update set title=excluded.title,description=excluded.description,category=excluded.category,region=excluded.region,difficulty=excluded.difficulty,points=excluded.points,instructions=excluded.instructions,icon=excluded.icon,featured=excluded.featured,region_order=excluded.region_order,step_order=excluded.step_order,lesson=excluded.lesson,quiz_question=excluded.quiz_question,answer_options=excluded.answer_options,source_url=excluded.source_url,active=excluded.active;
insert into public.mission_answers select id,2 from public.missions where mission_code='se_samba' on conflict(mission_id) do update set correct_index=excluded.correct_index;
insert into public.missions(title,description,category,region,difficulty,points,instructions,icon,featured,mission_code,region_order,step_order,lesson,quiz_question,answer_options,source_url,active) values('No baile caiçara','O fandango caiçara combina música, dança, poesia e convivência. Tem forte presença em comunidades do litoral paranaense e paulista, cruzando a divisão entre Sul e Sudeste. Instrumentos como violas e rabecas participam das apresentações. Os repertórios e as formas de dançar variam entre grupos. As culturas viajam e não cabem certinho nas fronteiras do mapa.','Música & dança','Sul','Fácil',160,array['Escolha uma das expressões que conheceu na viagem e escreva como ela pode conectar pessoas de lugares diferentes.'],'music',true,'su_fandango',5,1,'O fandango caiçara combina música, dança, poesia e convivência. Tem forte presença em comunidades do litoral paranaense e paulista, cruzando a divisão entre Sul e Sudeste. Instrumentos como violas e rabecas participam das apresentações. Os repertórios e as formas de dançar variam entre grupos. As culturas viajam e não cabem certinho nas fronteiras do mapa.','O fandango caiçara mostra que as culturas...',array['Podem atravessar fronteiras entre regiões','Existem só em capitais','São iguais em todas as comunidades'],'https://bcr.iphan.gov.br/bens-culturais/fandango-caicara/',true) on conflict(mission_code) do update set title=excluded.title,description=excluded.description,category=excluded.category,region=excluded.region,difficulty=excluded.difficulty,points=excluded.points,instructions=excluded.instructions,icon=excluded.icon,featured=excluded.featured,region_order=excluded.region_order,step_order=excluded.step_order,lesson=excluded.lesson,quiz_question=excluded.quiz_question,answer_options=excluded.answer_options,source_url=excluded.source_url,active=excluded.active;
insert into public.mission_answers select id,0 from public.missions where mission_code='su_fandango' on conflict(mission_id) do update set correct_index=excluded.correct_index;
insert into public.missions(title,description,category,region,difficulty,points,instructions,icon,featured,mission_code,region_order,step_order,lesson,quiz_question,answer_options,source_url,active) values('Histórias em uma cuia','O chimarrão é preparado com erva-mate e água quente e tem forte presença na cultura gaúcha. Os usos da erva-mate têm raízes indígenas e atravessam fronteiras do Brasil. O mate aparece em diferentes bebidas e costumes. A cuia pode ser um convite à conversa, mas cada pessoa e comunidade tem seu jeito de participar.','Sabores & encontros','Sul','Médio',170,array['Imagine uma roda de conversa sobre os Brasis. Qual pergunta você faria para conhecer a história de alguém de outra região?'],'food',false,'su_mate',5,2,'O chimarrão é preparado com erva-mate e água quente e tem forte presença na cultura gaúcha. Os usos da erva-mate têm raízes indígenas e atravessam fronteiras do Brasil. O mate aparece em diferentes bebidas e costumes. A cuia pode ser um convite à conversa, mas cada pessoa e comunidade tem seu jeito de participar.','Qual planta está na base do chimarrão?',array['Cacau','Erva-mate','Café'],'https://www.gov.br/turismo/pt-br/assuntos/ultimas-noticia/chimarrao-e-celebrado-como-simbolo-da-cultura-gaucha/',true) on conflict(mission_code) do update set title=excluded.title,description=excluded.description,category=excluded.category,region=excluded.region,difficulty=excluded.difficulty,points=excluded.points,instructions=excluded.instructions,icon=excluded.icon,featured=excluded.featured,region_order=excluded.region_order,step_order=excluded.step_order,lesson=excluded.lesson,quiz_question=excluded.quiz_question,answer_options=excluded.answer_options,source_url=excluded.source_url,active=excluded.active;
insert into public.mission_answers select id,1 from public.missions where mission_code='su_mate' on conflict(mission_id) do update set correct_index=excluded.correct_index;
insert into public.missions(title,description,category,region,difficulty,points,instructions,icon,featured,mission_code,region_order,step_order,lesson,quiz_question,answer_options,source_url,active) values('A festa continua!','O boi de mamão é uma brincadeira popular de Santa Catarina que reúne personagens, música, dança e encenação. O boi, a Maricota e outros personagens aparecem em diferentes grupos e versões. Famílias, artistas e comunidades mantêm a festa viva ao recriá-la. Sua viagem termina aqui, mas as histórias dos Brasis continuam muito além destas quinze paradas.','Festas & personagens','Sul','Médio',180,array['Crie o nome e uma característica de um personagem autoral para uma festa imaginária. Depois, conte qual descoberta desta viagem mais chamou sua atenção.'],'party',false,'su_boi',5,3,'O boi de mamão é uma brincadeira popular de Santa Catarina que reúne personagens, música, dança e encenação. O boi, a Maricota e outros personagens aparecem em diferentes grupos e versões. Famílias, artistas e comunidades mantêm a festa viva ao recriá-la. Sua viagem termina aqui, mas as histórias dos Brasis continuam muito além destas quinze paradas.','O que compõe a brincadeira do boi de mamão?',array['Somente uma competição esportiva','Somente uma exposição de objetos','Personagens, música, dança e encenação'],'https://ndi.ufsc.br/projetos-em-andamento/arte-educacao/boi-de-mamao/',true) on conflict(mission_code) do update set title=excluded.title,description=excluded.description,category=excluded.category,region=excluded.region,difficulty=excluded.difficulty,points=excluded.points,instructions=excluded.instructions,icon=excluded.icon,featured=excluded.featured,region_order=excluded.region_order,step_order=excluded.step_order,lesson=excluded.lesson,quiz_question=excluded.quiz_question,answer_options=excluded.answer_options,source_url=excluded.source_url,active=excluded.active;
insert into public.mission_answers select id,2 from public.missions where mission_code='su_boi' on conflict(mission_id) do update set correct_index=excluded.correct_index;

