create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$
begin
 insert into public.profiles(id,nickname,legacy_points) values(new.id,
 left(coalesce(nullif(trim(new.raw_user_meta_data->>'nickname'),''),'Viajante'),40),0);
 return new;
end $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();

-- Remove só a função anterior, nunca as contas ou o histórico.
drop function if exists public.mission_action(bigint,boolean);
create or replace function public.mission_action(p_mission_id bigint,p_complete boolean default false,
 p_answer integer default null,p_note text default '')
returns jsonb language plpgsql security definer set search_path='' as $$
declare
 uid uuid := auth.uid(); m public.missions%rowtype; s text;
 total integer; days_count integer; score integer; region_count integer; new_badges text[]; expected integer;
begin
 if uid is null then raise exception 'Entre na sua conta para continuar a viagem.'; end if;
 perform 1 from public.profiles where id=uid for update;
 if not found then raise exception 'Perfil não encontrado. Confira a configuração do banco.'; end if;
 select * into m from public.missions where id=p_mission_id and active and mission_code is not null;
 if not found then raise exception 'Esta parada não está disponível.'; end if;
 select status into s from public.user_missions where user_id=uid and mission_id=m.id;
 if s='completed' then return jsonb_build_object('awarded',0,'achievements','[]'::jsonb,'correct',true); end if;
 if exists(
  select 1 from public.missions prev where prev.active and prev.mission_code is not null
   and (prev.region_order,prev.step_order)<(m.region_order,m.step_order)
   and not exists(select 1 from public.user_missions um where um.user_id=uid and um.mission_id=prev.id and um.status='completed')
 ) then raise exception 'Complete as paradas anteriores para liberar este destino.'; end if;
 if p_complete is not true then
  insert into public.user_missions(user_id,mission_id,status) values(uid,m.id,'in_progress') on conflict do nothing;
  return jsonb_build_object('awarded',0,'achievements','[]'::jsonb);
 end if;
 if s is distinct from 'in_progress' then raise exception 'Embarque nesta missão antes de concluir.'; end if;
 select correct_index into expected from public.mission_answers where mission_id=m.id;
 if expected is null then raise exception 'Esta missão está sem resposta configurada.'; end if;
 if p_answer is distinct from expected then return jsonb_build_object('awarded',0,'correct',false,'achievements','[]'::jsonb); end if;
 if p_note is null or char_length(trim(p_note))<8 or char_length(p_note)>600 then
  raise exception 'Escreva sua descoberta no diário usando de 8 a 600 caracteres.';
 end if;
 update public.user_missions set status='completed',completed_at=now(),note=trim(p_note) where user_id=uid and mission_id=m.id;
 update public.profiles set points=points+m.points where id=uid returning points into score;
 select count(*),count(distinct (um.completed_at at time zone 'America/Sao_Paulo')::date)
 into total,days_count from public.user_missions um join public.missions mi on mi.id=um.mission_id
 where um.user_id=uid and um.status='completed' and mi.active and mi.mission_code is not null;
 select count(*) into region_count from (
  select mi.region_order from public.missions mi left join public.user_missions um
   on um.mission_id=mi.id and um.user_id=uid and um.status='completed'
  where mi.active and mi.mission_code is not null group by mi.region_order having count(*)=count(um.mission_id)
 ) done_regions;
 with added as (
  insert into public.user_achievements(user_id,achievement_id)
  select uid,id from public.achievements where active and
   case metric when 'missions' then total when 'days' then days_count when 'points' then score when 'regions' then region_count end >= target
  on conflict do nothing returning achievement_id
 ) select coalesce(array_agg(achievement_id),array[]::text[]) into new_badges from added;
 return jsonb_build_object('awarded',m.points,'achievements',to_jsonb(new_badges),'correct',true,'regions_completed',region_count);
end $$;

create or replace function public.leaderboard()
returns table(user_id uuid,nickname text,points integer,"position" bigint)
language sql stable security definer set search_path='' as $$
 with ranked as (
 select p.id,p.nickname,p.points,row_number() over(order by p.points desc,p.created_at,p.id) as pos
 from public.profiles p where auth.uid() is not null
 ) select id,nickname,points,pos from ranked where pos<=100 or id=auth.uid() order by pos;
$$;

alter table public.profiles enable row level security;
alter table public.missions enable row level security;
alter table public.user_missions enable row level security;
alter table public.achievements enable row level security;
alter table public.user_achievements enable row level security;
drop policy if exists own_profile on public.profiles;
drop policy if exists visible_missions on public.missions;
drop policy if exists own_missions on public.user_missions;
drop policy if exists visible_achievements on public.achievements;
drop policy if exists own_achievements on public.user_achievements;
create policy own_profile on public.profiles for select to authenticated using(id=auth.uid());
create policy visible_missions on public.missions for select to authenticated using(active and mission_code is not null);
create policy own_missions on public.user_missions for select to authenticated using(user_id=auth.uid());
create policy visible_achievements on public.achievements for select to authenticated using(active);
create policy own_achievements on public.user_achievements for select to authenticated using(user_id=auth.uid());
revoke all on public.profiles,public.missions,public.user_missions,public.achievements,public.user_achievements from anon,authenticated;
grant select on public.profiles,public.missions,public.user_missions,public.achievements,public.user_achievements to authenticated;
revoke all on function public.mission_action(bigint,boolean,integer,text) from public,anon;
revoke all on function public.leaderboard() from public,anon;
revoke all on function public.handle_new_user() from public,anon,authenticated;
grant execute on function public.mission_action(bigint,boolean,integer,text),public.leaderboard() to authenticated;

-- Histórico anterior é preservado; ranking cultural começa com as missões culturais.
update public.profiles p set points=coalesce((
 select sum(m.points) from public.user_missions um join public.missions m on m.id=um.mission_id
 where um.user_id=p.id and um.status='completed' and m.active and m.mission_code is not null
),0);
notify pgrst,'reload schema';
commit;
